-- The whole MySQL schema for Crosswords, generated by Hibernate from the entities (15 Nov 2026, after slice 31).
-- dev: not needed, ddl-auto=update creates and updates the tables itself.
-- prod: ddl-auto=validate creates nothing, so run this once on an empty database before the first start.
-- Grid templates, permissions and the two roles (the role matrix) are not here: InitData inserts them at startup.
-- Slice 22: solve_attempt. Slice 23: crossword_submission.solve_attempt_id. Slice 24: app_user.email unique.
-- Slice 31: role, permission and role_permission; app_user.role_id replaces the old app_user.role column.

create table api_call (crossword_id integer not null, duration_ms integer not null, estimated_wh float(53) not null, id integer not null auto_increment, input_tokens integer, output_tokens integer, submission_id integer, created_on datetime(6), api_name enum ('CLAUDE_SOLVE','TEXS_CLUES','TEXS_FILL'), llm_model enum ('CHEAP_AND_DUMB','SMARTER_AND_PRICIER','TOTAL_TOKEN_KILLER'), primary key (id)) engine=InnoDB;
create table app_user (id integer not null auto_increment, role_id integer, email varchar(255) not null, password_hash varchar(255), username varchar(255) not null, primary key (id)) engine=InnoDB;
create table crossword (grid_template_id integer, id integer not null auto_increment, user_id integer, created_on datetime(6), answer_key_json TEXT not null, empty_puzzle_json TEXT not null, player_prompt varchar(255), primary key (id)) engine=InnoDB;
create table crossword_submission (crossword_id integer not null, id integer not null auto_increment, percent_correct integer not null, solve_attempt_id integer, time_to_solve_ms integer not null, user_id integer, created_on datetime(6), submitted_grid_json TEXT not null, llm_model enum ('CHEAP_AND_DUMB','SMARTER_AND_PRICIER','TOTAL_TOKEN_KILLER'), primary key (id)) engine=InnoDB;
create table grid_template (id integer not null auto_increment, layout varchar(255) not null, name varchar(255) not null, primary key (id)) engine=InnoDB;
create table permission (id integer not null auto_increment, description varchar(255), name varchar(64) not null, primary key (id)) engine=InnoDB;
create table role (id integer not null auto_increment, description varchar(255), name varchar(255) not null, primary key (id)) engine=InnoDB;
create table role_permission (permission_id integer not null, role_id integer not null, primary key (permission_id, role_id)) engine=InnoDB;
create table solve_attempt (crossword_id integer not null, id integer not null auto_increment, user_id integer not null, started_on datetime(6) not null, primary key (id)) engine=InnoDB;
